1://! Summaries of CSV-like text: row counts, column totals and a per-key tally.
2:
3:use std::collections::BTreeMap;
4:
5:/// Splits one line on commas, trimming each field.
6:pub fn fields(line: &str) -> Vec<&str> {
7:    line.split(',').map(|f| f.trim()).collect()
8:}
9:
10:/// Sum of the numeric column `col` over every data row (the first line is a header).
11:pub fn column_total(text: &str, col: usize) -> f64 {
12:    let mut total = 0.0;
13:    for line in text.lines().skip(1) {
14:        let row = fields(line);
15:        total += row[col].parse::<f64>().unwrap_or(0.0);
16:    }
17:    total
18:}
19:
20:/// How many data rows carry each value of column `col`.
21:pub fn tally(text: &str, col: usize) -> BTreeMap<String, usize> {
22:    let mut out = BTreeMap::new();
23:    for line in text.lines().skip(1) {
24:        let row = fields(line);
25:        *out.entry(row[col].to_string()).or_insert(0) += 1;
26:    }
27:    out
28:}
29:
30:/// The mean of column `col`, or None for no rows.
31:pub fn mean(text: &str, col: usize) -> Option<f64> {
32:    let rows = text.lines().count();
33:    if rows == 0 {
34:        return None;
35:    }
36:    Some(column_total(text, col) / rows as f64)
37:}
